def run_init():
    """Run the init wizard."""
    ws = get_workspace()
    env_path = ws / ".env"
    data_dir = ws / "data"

    console.print(Panel.fit(
        "[bold green]MOSS Init[/bold green]\n"
        f"Workspace: {ws}",
        border_style="green",
    ))

    # Check Java
    has_java = _check_java()
    if has_java:
        console.print("[green]✓[/green] Java detected — HermiT OWL 2 DL reasoning available")
    else:
        console.print("[yellow]⚠[/yellow] Java not found — will use Python-Fallback reasoning")
        console.print("  Install Java (JDK 11+) for full HermiT reasoning: https://adoptium.net/")

    # LLM provider selection
    console.print("\n[bold]LLM Provider:[/bold]")
    console.print("  1. Local Ollama (recommended, zero external dependency)")
    console.print("  2. Cloud API (OpenAI-compatible: GLM, DeepSeek, OpenAI, etc.)")
    console.print("  3. Skip (use demo mode without LLM)")

    choice = click.prompt("Select", type=click.Choice(["1", "2", "3"]), default="1")

    if choice == "1":
        llm_url = "http://localhost:11434/v1/chat/completions"
        llm_key = "empty"
        llm_model = "qwen2.5:7b"
        console.print("[green]✓[/green] Ollama selected. Run: ollama pull qwen2.5:7b")
    elif choice == "2":
        llm_url = click.prompt("API URL", default="https://open.bigmodel.cn/api/paas/v4/chat/completions")
        llm_key = click.prompt("API Key", hide_input=True)
        llm_model = click.prompt("Model name", default="glm-4.7-fp8")
    else:
        llm_url = "http://localhost:11434/v1/chat/completions"
        llm_key = "empty"
        llm_model = "qwen2.5:7b"
        console.print("[yellow]⚠[/yellow] Skipped — LLM features will not work until configured")

    api_token = secrets.token_urlsafe(24)

    # Write .env
    env_content = _ENV_TEMPLATE.format(
        llm_url=llm_url, llm_key=llm_key, llm_model=llm_model,
        api_token=api_token,
    )
    env_path.write_text(env_content, encoding="utf-8")
    console.print(f"\n[green]✓[/green] Config written: {env_path}")

    # Create data dir
    data_dir.mkdir(parents=True, exist_ok=True)
    console.print(f"[green]✓[/green] Data directory: {data_dir}")

    console.print(Panel.fit(
        "[bold green]Setup complete![/bold green]\n\n"
        "Next steps:\n"
        "  moss demo      Load demo data\n"
        "  moss serve     Start web dashboard\n"
        "  moss ingest    Import a document",
        border_style="green",
    ))


def load_demo_seed():
    """Load demo seed data into the database."""
    from moss.models import (
        Assignment, Decision, GovernanceGraph, Issue, Update,
    )
    from moss.storage import Storage

    storage = Storage()
    graph = GovernanceGraph()

    for d in _DEMO_SEED["decisions"]:
        from datetime import datetime
        deadline = None
        if d.get("deadline"):
            try:
                deadline = datetime.fromisoformat(d["deadline"])
            except (ValueError, TypeError):
                pass
        graph.decisions[d["id"]] = Decision(
            id=d["id"], title=d["title"], source=d["source"],
            owner=d.get("owner"), department=d.get("department"),
            dependency=d.get("dependency"),
            status=d.get("status", "OPEN"),
            progress=d.get("progress", 0.0),
            risk_level=d.get("risk_level", "LOW"),
            deadline=deadline,
            raw_statement=d.get("raw_statement", ""),
        )

    for issue in _DEMO_SEED["issues"]:
        graph.issues[issue["id"]] = Issue(
            id=issue["id"], title=issue["title"],
            description=issue.get("description", ""),
            severity=issue.get("severity", "MEDIUM"),
        )

    for u in _DEMO_SEED["updates"]:
        graph.updates.append(Update(
            id=u["id"], decision_id=u["decision_id"],
            content=u["content"], progress=u.get("progress"),
            source=u.get("source", "demo"),
        ))

    for a in _DEMO_SEED["assignments"]:
        graph.assignments.append(Assignment(
            decision_id=a["decision_id"], owner=a["owner"],
            department=a.get("department"),
        ))

    graph.edges = _DEMO_SEED["edges"]
    storage.save(graph)
    return graph
